import { site } from "~/data/constants";

/**
 * The brand lockup: mark + wordmark (480 x 278), generated by
 * scripts/prepare-logo.ps1 from logo/Creaova_Logo1.png.
 *
 * Three things this component is responsible for:
 *
 * 1. **Intrinsic dimensions are always present.** Without them the header
 *    reflows the moment the image decodes. They live in `site.logo` next to the
 *    paths and must stay in sync with the real files.
 *
 * 2. **`alt` defaults to empty, deliberately.** In the navbar this sits inside a
 *    link that is already labelled "Creaova — home". Giving the image
 *    alt="Creaova" as well makes a screen reader announce the brand twice for
 *    one link. Pass an explicit `alt` only where the image carries the meaning
 *    on its own (the footer lockup).
 *
 * 3. **`variant` picks the surface.** The artwork is orange + ink wordmark, so
 *    on a dark panel the ink wordmark would disappear. The inverse variant is
 *    flat white, the only treatment guaranteed to read there (see the reasoning
 *    in scripts/prepare-logo.ps1).
 */
export function Logo({
  variant = "ink",
  alt = "",
  priority = false,
  className = "h-11",
}: {
  variant?: "ink" | "inverse";
  alt?: string;
  /** Above-the-fold only: opts out of lazy loading and raises fetch priority. */
  priority?: boolean;
  className?: string;
}) {
  return (
    <img
      src={variant === "inverse" ? site.logo.inverseSrc : site.logo.src}
      alt={alt}
      width={site.logo.width}
      height={site.logo.height}
      decoding="async"
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      className={`w-auto ${className}`}
    />
  );
}
